  "settings.modelHelp": "사용처: AI 채팅, 점검(AI 분석), 출처 대조, 토픽 통합, 채팅과 노트 제목, 일반 지식 대조. 표준 작업·정밀 작업을 비워 두면 그것도 이 모델을 씁니다. 가벼운 작업이 중심이라 빠른 모델이나 로컬 모델(LM Studio 등)로도 충분합니다.",
