  "settings.insightTest.empty": "후보가 없습니다. 테스트용 지견에는 묶을 수 있는 패턴을 일부러 넣어 두었으므로, 결과가 비어 있다면 이 모델은 인사이트 추상화를 어려워할 가능성이 높습니다. 더 상위 모델로 시험해 보세요.",
  "settings.insightTest.sources": "지견 {count}개 인용",
  "settings.insightTest.sourcesNums": "인용: {nums}",
  "settings.insightTest.summary": "묶음 {folds}개 · 바꿔 말하기 가능성 {restates}개 · 살펴봄 {covered}/{total}",
  "settings.insightTest.oneOffCited": "(지견 3도 인용함 — 바꿔 말한 것이 아니라 추상화했다면 괜찮음)",
  "settings.insightTest.oneOffRestated": "(지견 3을 바꿔 말한 그대로 가져왔습니다)",
  "settings.insightTest.restatement": "바꿔 말하기 가능성",
  "settings.insightTest.referenceFolds": "묶는 지견: {nums}",
  "settings.insightTest.referenceNote": "핵심 통과 기준은 여러 지견을 묶어 이 예시 수준으로 추상화한 인사이트가 나오는 것입니다. 성능이 좋은 모델은 타당한 추가 후보(구조를 다른 관점에서 해석한 인사이트, 또는 지견 3을 추상화해 일상적인 표현으로 쓴 독립 인사이트)를 내기도 하며, '바꿔 말하기' 배지가 없다면 문제없습니다. 단순히 바꿔 말한 결과만 나열되거나 목록이 비어 있으면 추상화 능력이 부족하다는 신호입니다. 테스트는 실제 인사이트 발견과 같은 다단계 파이프라인을 거치므로 수십 초에서 몇 분이 걸릴 수 있습니다.",
  "settings.insightTest.clear": "결과 지우기",
  "settings.groundingModelInfo": "일반 지식 대조는 위의 채팅 모델을 씁니다. 판단 결과는 이 컴퓨터에 저장되어, 비슷한 진술은 다음부터 바로 확인됩니다.",
  "settings.autoGrounding.title": "새 지식을 자동으로 대조",
  "settings.autoGrounding.help": "새로 만든 인사이트와 지견을 백그라운드에서 하나씩 자동으로 일반 지식과 대조합니다(기본값: 끔). 대조 데이터를 먼저 보고 아직 없는 진술만 모델로 판단하므로, 쓸수록 대조 데이터가 늘어 대조가 빠르고 저렴해집니다. 같은 일반 지식 항목과 대조된 인사이트끼리는 자동으로 연결됩니다.",
  "settings.features.worldGrounding.title": "일반 지식 대조 사용",
  "settings.features.worldGrounding.help": "일반 지식 대조는 성능 좋은 모델일수록 판단이 정확합니다. 끄면 대조 버튼과 열이 숨겨집니다. 기존 결과는 남습니다.",
  "settings.features.claims.title": "지견 사용",
  "settings.features.claims.summary": "자료에 담긴 명제를 하나씩 지견으로 뽑아냅니다",
  "settings.features.claims.help": "지견은 Graphium 고유의 확장으로, 노트나 문서에 담긴 명제(예: 'Y일 때 X가 일어난다')를 모두 뽑아냅니다. 실험 고유의 세부 사항은 빼서 다른 맥락에서도 통하게 씁니다. 토픽은 지견과 별도로 원본 자료에서 바로 만들어집니다. 인사이트는 지견으로 만들기 때문에 지견을 끄면 인사이트도 꺼집니다. 끄면 지식 베이스에 추가할 때 지견을 추출하지 않고, 원본 텍스트로 토픽만 만듭니다. 기존 지견과 인사이트는 남아 계속 볼 수 있습니다.",
  "settings.features.sourceSummaries.title": "자료마다 요약 페이지 쓰기",
  "settings.features.sourceSummaries.summary": "지식 베이스에 추가한 PDF나 URL마다 요약 페이지를 만듭니다",
  "settings.features.sourceSummaries.help": "노트와 Word 파일에는 만들지 않습니다. 자료 하나를 추가할 때마다 AI 호출이 한 번 늘어납니다. 요약은 토픽과 같은 규칙(문장마다 출처 인용)으로 쓰이며 출처 대조를 할 수 있습니다. 같은 자료를 다시 추가하면 기존 요약 페이지를 다시 씁니다.",
  "settings.features.insights.title": "인사이트 사용",
  "settings.features.insights.help": "각 인사이트는 원래 지견과 연결됩니다. 인사이트는 성능 좋은 모델일수록 품질이 좋아집니다. 끄면 사이드바와 목록에서 숨겨집니다. 기존 인사이트는 남습니다.",
  "settings.features.insights.disabledByClaimsOff": "인사이트는 지견으로 만들기 때문에, 지견이 꺼져 있는 동안에는 쓸 수 없습니다.",
  "settings.ai.sectionAssign": "모델 지정",
