  "settings.aiStatus.missingTitle": "고른 모델 중 쓸 수 없는 모델이 있습니다",
  "settings.aiStatus.missingDesc": "고른 모델({names})을 지금 설정에서는 쓸 수 없습니다. 이름이 바뀌었거나 삭제되었거나, 그 항목에 맞는 종류의 모델이 아닐 수 있습니다. 다시 고르거나, 이대로 저장하면 기본값으로 돌아갑니다.",
