  "experimental.label": "선공개",
  "experimental.tooltip": "선공개 기능입니다. 쓸 수 있지만 얼마나 도움이 되는지 확인하는 단계라서, 동작 방식과 결과가 바뀔 수 있습니다.",
  "settings.ai.sectionGrounding": "일반 지식 대조",
  "settings.ai.sectionSourceCheck": "출처 대조",
  "settings.ai.sectionClaims": "지견",
  "settings.ai.sectionAsterism": "Asterism 연동",
  "settings.features.worldGrounding.summary": "쓴 내용이 세상에 이미 알려진 지식과 맞는지 확인합니다.",
  "settings.autoGrounding.summary": "새 인사이트와 지견을 백그라운드에서 대조합니다",
  "settings.autoSourceCheck.title": "자동으로 출처 대조",
  "settings.autoSourceCheck.help": "새로 만들거나 업데이트한 지견과 토픽을 백그라운드에서 하나씩 출처와 대조합니다(기본값: 끔). 켜면 아직 대조하지 않은 항목도 차례로 대조합니다. 출처 하나마다 AI를 한 번 호출합니다.",
  "settings.autoSourceCheck.summary": "새 지견과 토픽을 백그라운드에서 출처와 대조합니다",
  "settings.agenticSearch.title": "충분히 찾아본 뒤 답하기",
  "settings.agenticSearch.summary": "첫 검색으로 부족하면 AI가 노트를 더 찾아본 뒤 답합니다",
  "settings.agenticSearch.help": "내부 참조나 외부 참조 채팅에서 씁니다. 첫 검색으로 부족하면 AI가 표현을 바꿔 노트, 토픽, 지견, 자료를 다시 찾고, 일부만으로 부족한 페이지는 전체를 읽고, 스텝과 내력을 따라간 뒤 답합니다. 질문 하나에 여러 번 찾아볼 수 있어 답이 나오기까지 오래 걸리고 AI 사용량도 늘어납니다. 읽기만 하며 아무것도 바꾸지 않습니다(기본값: 끔. 에이전틱 검색(agentic search)이라고 부르는 방식입니다). 켜져 있을 때는 모델 지정의 '정밀 작업 모델'로 답합니다(강한 모델일수록 답이 좋아지기 때문입니다).",
  "settings.features.autoFullCheck.title": "자동 점검에서 전체(AI) 분석 실행",
  "settings.features.autoFullCheck.summary": "자동 점검에서 모순과 빈틈도 AI로 살펴봅니다",
  "settings.features.autoFullCheck.help": "끄면 자동으로 실행되는 점검(추가 직후, 그리고 시작할 때 24시간마다 한 번)은 LLM을 호출하지 않는 기계적 점검(모순, 구조상 고립이나 중복 의심)만 합니다. 켜면 같은 자동 점검에서 AI 분석(빈틈, 중복, 약한 인용 등)까지 합니다. 어느 쪽이든 발견한 문제를 고치거나 통합하거나 연결하는 것은 언제나 사용자가 정합니다. 자동으로 적용되는 것은 없습니다. 이 설정과 관계없이 유지관리 화면에서 언제든 전체 점검을 직접 실행할 수 있습니다.",
  "settings.features.asterism.title": "Asterism과 연동",
  "settings.features.asterism.summary": "인사이트를 지식 그래프인 Asterism에 넘깁니다",
  "settings.features.asterism.help": "Asterism이 규칙에 어긋나는 관찰을 찾을 수 있게 합니다. 인사이트를 Asterism(지식 그래프 플랫폼)에 넘기는 내보내기를 켭니다. 이 기능을 꺼도 Graphium의 모든 기능을 쓸 수 있습니다. 꺼져 있는 동안에는 Asterism 설정, 인사이트 페이지의 Asterism 블록, 내보내기가 숨겨지고 유형도 자동으로 지정하지 않습니다. 이미 쓰인 유형과 근거는 그대로 남습니다.",
  "settings.features.insights.summary": "지견에 담긴 관계를 다른 맥락에서도 통하도록 일반화합니다",
  "settings.modelFit.label": "모델 안내",
  "settings.modelFit.class.frontier": "상위 클라우드",
  "settings.modelFit.class.frontier.help": "각 회사의 주력 모델(유료 API나 Copilot으로 쓰는 것)",
  "settings.modelFit.class.openLarge": "공개 대형",
