  "asterismExport.description": "Asterism에 데이터셋으로 가져오기 위한, 유형별·조건별로 나눈 JSON 파일입니다. zip으로 묶지 않고 아래 파일을 각자의 이름으로 하나씩 저장합니다. Asterism에서는 이 파일들을 골라 가져와 주세요. 각 행의 iri 열은 지견의 IRI이며, 하위 파일은 상위 항목의 iri로 연결됩니다. PROV-JSON-LD 내보내기와는 다른 형식입니다.",
