  "composer.verb.prompt.contradiction": "이 노트에서 인용한 지견과 인사이트를 살펴보고, 그 사이의 모순이나 긴장을 찾아 주세요. 각각 어느 인용과 어느 인용이 어떤 점에서 충돌하는지 구체적으로 밝혀 주세요.",
  "composer.verb.prompt.gaps": "이 노트에서 인용한 지견과 인사이트를 하나의 묶음으로 보고, 빠진 것을 지적해 주세요. 검증되지 않은 전제, 다루지 않은 경우, 아직 뒷받침되지 않은 추론 단계 등을 들어 주세요.",
  "composer.verb.prompt.nextValidation": "이 노트에서 인용한 지견과 인사이트를 바탕으로, 다음에 하면 가장 많은 정보를 얻을 실험이나 검증 단계를 제안해 주세요. 각각이 무엇을 확인하고 무엇을 배제할 수 있는지도 설명해 주세요.",
  "composer.verb.prompt.alternative": "이 노트에서 인용한 지견과 인사이트를 바탕으로, 지금 방향과 다른 접근이나 해석을 제안해 주세요.",
  "composer.verb.prompt.counterexample": "이 노트에서 인용한 지견과 인사이트가 성립하지 않는 반례나 조건을 찾아 주세요.",
  "composer.verb.prompt.analogy": "이 노트에서 인용한 지견과 인사이트와 닮은 인접 분야의 사례나 패턴을 들고, 무엇을 옮겨 쓸 수 있을지 밝혀 주세요.",
  "composer.insertProv.systemHint": "다음 설명을 절차 스텝으로 나눠 주세요. 각 스텝은 앞에 [[label:procedure]]를 붙인 H2 제목(## ...)으로 씁니다. 각 스텝 본문에서는 인풋을 [[m]]...[[/m]], 툴을 [[t]]...[[/t]], 파라미터를 [[a]]...[[/a]], 아웃풋을 [[o]]...[[/o]]로 해당 텍스트 범위를 감싸 표시해 주세요. 본문 블록 앞에 예전 방식의 [Step]/[Input]/[Tool]/[Output] 라벨은 붙이지 마세요.",
